"""Deterministic constrained constructor for 26 circles in a unit square."""
import numpy as np


def compute_max_radii(centers):
    n = len(centers)
    r = np.minimum.reduce((centers[:, 0], centers[:, 1],
                           1.0 - centers[:, 0], 1.0 - centers[:, 1])).copy()
    for i in range(n):
        for j in range(i + 1, n):
            d = float(np.linalg.norm(centers[i] - centers[j]))
            if r[i] + r[j] > d and r[i] + r[j] > 0:
                t = d / (r[i] + r[j])
                r[i] *= t
                r[j] *= t
    return np.maximum(r, 0.0)


def _row_seed(counts, offsets, phase=0.0):
    ys = np.linspace(0.095, 0.905, len(counts))
    pts = []
    for k, (m, off) in enumerate(zip(counts, offsets)):
        width = 0.79 + 0.018 * (m - 5)
        left, right = 0.5 - width / 2 + off, 0.5 + width / 2 + off
        xs = np.linspace(left, right, m)
        stagger = 0.5 * (right - left) / max(1, m - 1) if k % 2 else 0.0
        for q, x in enumerate(xs):
            pts.append((
                np.clip(x + stagger + 0.0055 * np.sin(1.71*(k+1)*(q+1)+phase),
                        0.035, 0.965),
                np.clip(ys[k] + 0.0035 * np.cos(1.13*(k+1)*(q+1)+phase),
                        0.035, 0.965),
            ))
    return np.asarray(pts, dtype=float)


def _frame_seed(kind):
    if kind == 0:
        a, b, skew = 0.105, 0.895, 0.0
    elif kind == 1:
        a, b, skew = 0.085, 0.915, 0.012
    else:
        a, b, skew = 0.110, 0.890, -0.014
    pts = []
    for t in np.linspace(0.18, 0.82, 4):
        pts.extend(((t + skew, a), (t - skew, b),
                    (a, t - skew), (b, t + skew)))
    for y, sh in ((0.405, -0.035 + skew), (0.595, 0.035 - skew)):
        for x in np.linspace(0.19, 0.81, 5):
            pts.append((x + sh, y))
    return np.clip(np.asarray(pts), 0.035, 0.965)


def _cellular_seed(defect, power=0.0):
    grid = np.linspace(0.12, 0.88, 5)
    pts = []
    for row, y in enumerate(grid):
        for x in grid:
            pts.append((np.clip(x + (0.038 if row % 2 else 0), .035, .965), y))
    sites = np.asarray(pts + [defect], dtype=float)
    sample = np.linspace(.02, .98, 33)
    sample = np.asarray([(x, y) for y in sample for x in sample])
    weights = np.zeros(26)
    if power:
        for k, p in enumerate(sites):
            wall = min(p[0], p[1], 1-p[0], 1-p[1])
            weights[k] = power if wall < .18 else (-.35*power if wall > .30 else 0)
        weights[25] = -.15 * power
    corners = {0, 4, 20, 24}
    for _ in range(16):
        d = sample[:, None, :] - sites[None, :, :]
        labels = np.argmin(np.sum(d*d, axis=2) - weights[None, :], axis=1)
        nxt = sites.copy()
        for k in range(26):
            part = sample[labels == k]
            if len(part):
                rate = .10 if k in corners else .34
                nxt[k] += rate * (part.mean(axis=0) - nxt[k])
        sites = np.clip(nxt, .035, .965)
    return sites


def _radius_lp(centers, fallback):
    try:
        from scipy.optimize import linprog
        n = len(centers)
        A, b = [], []
        for i, (x, y) in enumerate(centers):
            row = np.zeros(n)
            row[i] = 1
            for lim in (x, y, 1-x, 1-y):
                A.append(row.copy())
                b.append(lim)
        for i in range(n):
            for j in range(i+1, n):
                row = np.zeros(n)
                row[i] = row[j] = 1
                A.append(row)
                b.append(float(np.linalg.norm(centers[i] - centers[j])))
        ans = linprog(-np.ones(n), A_ub=np.asarray(A), b_ub=np.asarray(b),
                      bounds=[(0.0, .25)] * n, method="highs")
        if ans.success and np.all(np.isfinite(ans.x)):
            return ans.x
    except Exception:
        pass
    return fallback


def _feasible(c, r, tol=5e-7):
    if c.shape != (26, 2) or r.shape != (26,) or not np.all(np.isfinite(c)):
        return False
    if not np.all(np.isfinite(r)) or np.min(r) < -tol:
        return False
    if np.min(np.column_stack((c[:, 0]-r, c[:, 1]-r,
                               1-c[:, 0]-r, 1-c[:, 1]-r))) < -tol:
        return False
    for i in range(26):
        d = c[i+1:] - c[i]
        if len(d) and np.min(np.sum(d*d, axis=1) - (r[i]+r[i+1:])**2) < -tol:
            return False
    return True


def construct_packing():
    n = 26
    seeds = [
        _row_seed((5, 5, 6, 5, 5), (0, .018, 0, .018, 0), 0),
        _row_seed((5, 6, 5, 5, 5), (0, -.018, .018, -.010, .012), .7),
        _row_seed((5, 5, 5, 6, 5), (.012, -.010, .018, -.018, 0), 1.4),
        _row_seed((4, 5, 4, 5, 4, 4), (0, .018, -.010, .018, 0, .012), 2.1),
        _row_seed((4, 5, 5, 4, 5, 3), (.008, -.014, .012, -.012, .014, 0), 2.8),
        _frame_seed(0), _frame_seed(1), _frame_seed(2),
        _cellular_seed((.50, .43)), _cellular_seed((.57, .52)),
        _cellular_seed((.50, .43), .0018), _cellular_seed((.57, .52), -.0018),
    ]
    bestc = seeds[0].copy()
    bestr = compute_max_radii(bestc)
    bestv = float(bestr.sum())

    try:
        from scipy.optimize import minimize
        ii, jj = np.triu_indices(n, 1)

        def objective(z):
            return -float(np.sum(z[2*n:]))

        def con(z):
            c, r = z[:2*n].reshape(n, 2), z[2*n:]
            d = c[jj] - c[ii]
            return np.concatenate((
                c[:, 0]-r, c[:, 1]-r, 1-c[:, 0]-r, 1-c[:, 1]-r,
                np.einsum("ij,ij->i", d, d) - (r[ii]+r[jj])**2))

        def solve(start, iters):
            z = np.concatenate((start.reshape(-1), np.full(n, .018)))
            ans = minimize(objective, z, method="SLSQP",
                           bounds=[(.001, .999)]*(2*n) + [(.001, .22)]*n,
                           constraints={"type": "ineq", "fun": con},
                           options={"maxiter": iters, "ftol": 3e-10,
                                    "disp": False})
            c, r = ans.x[:2*n].reshape(n, 2), ans.x[2*n:]
            return c, r

        candidates = []
        for seed in seeds:
            c, r = solve(seed, 550)
            if _feasible(c, r):
                candidates.append((float(r.sum()), c.copy(), r.copy()))

        candidates.sort(key=lambda x: x[0], reverse=True)

        def reinsert(parent, radii, weighted):
            middle = np.array((.5, .5))
            removed = np.argsort(np.linalg.norm(parent-middle, axis=1),
                                 kind="stable")[:8]
            keep = np.ones(n, dtype=bool)
            keep[removed] = False
            retained, rr = parent[keep].copy(), radii[keep].copy()
            grid = np.linspace(.16, .84, 37)
            avail = np.asarray([(x, y) for y in grid for x in grid])
            made = []
            for _ in range(8):
                clear = np.minimum.reduce((avail[:, 0], avail[:, 1],
                                           1-avail[:, 0], 1-avail[:, 1]))
                for k, p in enumerate(retained):
                    gap = np.linalg.norm(avail-p, axis=1)
                    clear = np.minimum(clear, gap - (rr[k] if weighted else 0))
                for p in made:
                    clear = np.minimum(clear, np.linalg.norm(avail-p, axis=1)-.024)
                choice = int(np.argmax(clear - 1e-10*np.linalg.norm(avail-middle, axis=1)))
                made.append(avail[choice].copy())
                avail = np.delete(avail, choice, axis=0)
            result = np.empty((n, 2))
            result[keep] = retained
            result[removed] = np.asarray(made)
            return result

        for _, parent, pr in candidates[:3]:
            for weighted in (False, True):
                c, r = solve(reinsert(parent, pr, weighted), 450)
                if _feasible(c, r):
                    candidates.append((float(r.sum()), c.copy(), r.copy()))

        candidates.sort(key=lambda x: x[0], reverse=True)
        for _, c, r in candidates[:8]:
            r = _radius_lp(c, r)
            if _feasible(c, r) and float(r.sum()) > bestv:
                bestv, bestc, bestr = float(r.sum()), c.copy(), r.copy()
    except (ImportError, ValueError, RuntimeError, FloatingPointError):
        pass

    bestr = np.maximum(0.0, bestr * (1.0 - 3e-7))
    return bestc, bestr, float(np.sum(bestr))


def run_packing():
    return construct_packing()


def visualize(centers, radii):
    import matplotlib.pyplot as plt
    from matplotlib.patches import Circle
    fig, ax = plt.subplots(figsize=(8, 8))
    ax.set_xlim(0, 1)
    ax.set_ylim(0, 1)
    ax.set_aspect("equal")
    ax.grid(True)
    for i, (c, r) in enumerate(zip(centers, radii)):
        ax.add_patch(Circle(c, r, alpha=.5))
        ax.text(c[0], c[1], str(i), ha="center", va="center")
    plt.title(f"Circle Packing (n={len(centers)}, sum={sum(radii):.6f})")
    plt.show()


if __name__ == "__main__":
    centers, radii, sum_radii = run_packing()
    print(f"Sum of radii: {sum_radii}")
    visualize(centers, radii)

